use super::clock::Clock;
use super::config::Config;
use super::error::AppError;
use super::fs::FileSystem;

/// launchd から呼ばれるラッパー。`run-job.sh <label> <command>`。
/// macOS 標準の /bin/bash 3.2 で動くよう、bash 4 以降の構文は使わない。
pub const WRAPPER_SCRIPT: &str = r#"#!/bin/bash
# launchagent-manager wrapper v1 (generated by launchagent-manager; do not edit)
# usage: run-job.sh <label> <command>
set -u

if [ "$#" -lt 2 ]; then
  echo "usage: $0 <label> <command>" >&2
  exit 64
fi

label="$1"
cmd="$2"

case "$label" in
  ''|.*|*[!A-Za-z0-9._-]*)
    echo "run-job.sh: invalid label: $label" >&2
    exit 64
    ;;
esac

base_dir="$(cd "$(dirname "$0")/.." 2>/dev/null && pwd -P)"
runs_dir="$base_dir/runs"
record="$runs_dir/$label.json"
mkdir -p "$runs_dir" 2>/dev/null

now_utc() {
  date -u +%Y-%m-%dT%H:%M:%SZ
}

# $1: started_at, $2: finished_at (JSON value), $3: exit_code (JSON value)
write_record() {
  tmp="$record.tmp.$$"
  if printf '{"version":1,"label":"%s","started_at":"%s","finished_at":%s,"exit_code":%s,"pid":%s}\n' \
      "$label" "$1" "$2" "$3" "$$" > "$tmp" 2>/dev/null; then
    mv -f "$tmp" "$record" 2>/dev/null || rm -f "$tmp" 2>/dev/null
  fi
  return 0
}

started="$(now_utc)"
write_record "$started" null null

/bin/bash -c "$cmd"
rc=$?

finished="$(now_utc)"
write_record "$started" "\"$finished\"" "$rc"

exit "$rc"
"#;

/// ラッパーと runs ディレクトリを用意する。内容が同じなら書き込まない。
pub fn ensure_wrapper(fs: &dyn FileSystem, clock: &dyn Clock, cfg: &Config) -> Result<(), AppError> {
    let bin_dir = cfg.wrapper_path.parent().ok_or_else(|| AppError::InvalidPath {
        path: cfg.wrapper_path.to_string_lossy().into(),
    })?;
    fs.create_dir_all(bin_dir)?;
    fs.create_dir_all(&cfg.runs_dir)?;
    if fs.exists(&cfg.wrapper_path) {
        if let Ok(current) = fs.read(&cfg.wrapper_path) {
            if current == WRAPPER_SCRIPT.as_bytes() {
                // 内容が同じでも実行権限は直しておく
                fs.set_mode(&cfg.wrapper_path, 0o755)?;
                return Ok(());
            }
        }
    }
    let tmp = bin_dir.join(format!(".run-job.sh.tmp-{}", clock.now_millis()));
    fs.write(&tmp, WRAPPER_SCRIPT.as_bytes())?;
    fs.set_mode(&tmp, 0o755)?;
    if let Err(e) = fs.rename(&tmp, &cfg.wrapper_path) {
        let _ = fs.remove_file(&tmp);
        return Err(e.into());
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::domain::fakes::{FakeFs, FixedClock, Journal};
    use std::path::Path;

    #[test]
    fn writes_wrapper_once() {
        let cfg = Config::from_home(Path::new("/home/u"), 501);
        let j = Journal::default();
        let fs = FakeFs::new(j.clone());
        ensure_wrapper(&fs, &FixedClock(1), &cfg).unwrap();
        assert_eq!(fs.get(&cfg.wrapper_path).unwrap(), WRAPPER_SCRIPT.as_bytes());
        assert!(fs.has_dir(&cfg.runs_dir));
        let writes = |j: &Journal| j.events().iter().filter(|e| matches!(e, crate::domain::fakes::Event::Write(_))).count();
        assert_eq!(writes(&j), 1);
        ensure_wrapper(&fs, &FixedClock(2), &cfg).unwrap();
        assert_eq!(writes(&j), 1);
    }

    #[test]
    fn rewrites_when_content_differs() {
        let cfg = Config::from_home(Path::new("/home/u"), 501);
        let fs = FakeFs::new(Journal::default()).with_file(&cfg.wrapper_path, "old");
        ensure_wrapper(&fs, &FixedClock(1), &cfg).unwrap();
        assert_eq!(fs.get(&cfg.wrapper_path).unwrap(), WRAPPER_SCRIPT.as_bytes());
    }
}
